import{c as d,Q as e,j as o,m as a}from"./chunks/framework.CWBTDBPu.js";const b=JSON.parse('{"title":"YuChat 配置说明","description":"","frontmatter":{"title":"YuChat 配置说明"},"headers":[],"relativePath":"plugins/items/yu-chat/config.md","filePath":"plugins/items/yu-chat/config.md"}'),r={name:"plugins/items/yu-chat/config.md"};function c(l,t,h,i,s,n){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="yuchat-配置说明" tabindex="-1">YuChat 配置说明 <a class="header-anchor" href="#yuchat-配置说明" aria-label="Permalink to &quot;YuChat 配置说明&quot;">​</a></h1><p>YuChat 首次启动会在 <code>plugins/YuChat/</code> 生成多份配置文件。插件升级时会按版本号合并缺失节点，正式服改配置前仍建议先备份。</p><h2 id="文件结构" tabindex="-1">文件结构 <a class="header-anchor" href="#文件结构" aria-label="Permalink to &quot;文件结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>作用</th></tr></thead><tbody><tr><td><code>config.yml</code></td><td>主配置：数据库、依赖加载、聊天格式、经济、昵称、显示同步、公告和声音。</td></tr><tr><td><code>messages.yml</code></td><td>命令提示、购买反馈、输入提示、GUI 状态和错误消息。</td></tr><tr><td><code>gui.yml</code></td><td>玩家 GUI 与管理员 GUI 的标题、按钮、材质、名称和 lore。</td></tr><tr><td><code>titles.yml</code></td><td>内置称呼配置。</td></tr><tr><td><code>custom_titles.yml</code></td><td>管理员 GUI 新建称呼保存位置。</td></tr><tr><td><code>effects.yml</code></td><td>颜色、渐变、彩虹、闪烁、循环等文本效果。</td></tr><tr><td><code>libs/</code></td><td>运行时下载的数据库与连接池依赖。</td></tr><tr><td><code>runtime/</code></td><td>发布版解压出的隔离 core jar。</td></tr></tbody></table><h2 id="library" tabindex="-1">library <a class="header-anchor" href="#library" aria-label="Permalink to &quot;library&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节点</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>library.enabled</code></td><td><code>true</code></td><td>是否启用运行时依赖解析。关闭后只使用服务端或插件包中已有依赖。</td></tr><tr><td><code>library.verify-checksum</code></td><td><code>true</code></td><td>是否校验依赖完整性。</td></tr><tr><td><code>library.fail-on-required-missing</code></td><td><code>true</code></td><td>必需依赖缺失时是否中止启动。当前依赖均按可恢复依赖处理。</td></tr><tr><td><code>library.connect-timeout-ms</code></td><td><code>15000</code></td><td>下载连接超时。</td></tr><tr><td><code>library.read-timeout-ms</code></td><td><code>60000</code></td><td>下载读取超时。</td></tr></tbody></table><h2 id="storage" tabindex="-1">storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;storage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节点</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>storage.type</code></td><td><code>sqlite</code></td><td><code>sqlite</code> 或 <code>mysql</code>。</td></tr><tr><td><code>storage.table-prefix</code></td><td><code>yuchat_</code></td><td>所有数据表统一前缀。</td></tr><tr><td><code>storage.pool.enabled</code></td><td><code>true</code></td><td>MySQL 推荐开启；SQLite 会自动使用单写连接降低 locked 风险。</td></tr><tr><td><code>storage.mysql.*</code></td><td>本地数据库示例</td><td>MySQL 主机、端口、库名、账号、密码和 JDBC 参数。</td></tr><tr><td><code>storage.sqlite.file</code></td><td><code>yuchat.db</code></td><td>SQLite 数据库文件名。</td></tr></tbody></table><h2 id="placeholder" tabindex="-1">placeholder <a class="header-anchor" href="#placeholder" aria-label="Permalink to &quot;placeholder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节点</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>placeholder.enabled</code></td><td><code>true</code></td><td>是否允许解析 PlaceholderAPI。</td></tr><tr><td><code>placeholder.expansion.enabled</code></td><td><code>true</code></td><td>是否注册 YuChat 自带 <code>%yuchat_*%</code> 变量。</td></tr></tbody></table><p>常见变量见 <a href="/YuPluginHub/plugins/items/yu-chat/placeholders">PlaceholderAPI</a>。</p><h2 id="prefix-suffix" tabindex="-1">prefix-suffix <a class="header-anchor" href="#prefix-suffix" aria-label="Permalink to &quot;prefix-suffix&quot;">​</a></h2><p><code>prefix-suffix</code> 控制 LuckPerms 前缀、后缀和 meta 的组合方式。</p><table tabindex="0"><thead><tr><th>节点</th><th>说明</th></tr></thead><tbody><tr><td><code>prefix-suffix.enabled</code></td><td>是否启用前后缀读取与显示。</td></tr><tr><td><code>prefix-suffix.empty-text</code></td><td>GUI 中无前缀/后缀时显示的文字。</td></tr><tr><td><code>prefix-suffix.placeholder-fallback</code></td><td>LuckPerms API 不可用时是否使用 PlaceholderAPI 兜底。</td></tr><tr><td><code>prefix-suffix.prefix.parts</code></td><td>前缀拼接片段，支持 <code>prefix</code>、<code>all-prefixes</code>、<code>meta:&lt;key&gt;</code>、<code>text:&lt;文本&gt;</code>、<code>placeholder:&lt;变量&gt;</code>。</td></tr><tr><td><code>prefix-suffix.suffix.parts</code></td><td>后缀拼接片段。</td></tr><tr><td><code>prefix-suffix.meta-keys</code></td><td>管理员 GUI 中常用 meta key 列表。</td></tr></tbody></table><h2 id="chat-format" tabindex="-1">chat-format <a class="header-anchor" href="#chat-format" aria-label="Permalink to &quot;chat-format&quot;">​</a></h2><p>聊天格式是 YuChat 的核心配置。</p><table tabindex="0"><thead><tr><th>节点</th><th>说明</th></tr></thead><tbody><tr><td><code>chat-format.enabled</code></td><td>是否接管玩家聊天格式。</td></tr><tr><td><code>chat-format.format</code></td><td>有称呼时的聊天格式。</td></tr><tr><td><code>chat-format.no-title-format</code></td><td>无称呼时的聊天格式。</td></tr><tr><td><code>chat-format.parse-placeholderapi</code></td><td>是否在聊天格式中解析 PlaceholderAPI。</td></tr><tr><td><code>chat-format.message-color.enabled</code></td><td>是否处理聊天内容颜色。</td></tr><tr><td><code>chat-format.message-color.legacy-permission</code></td><td>允许 <code>&amp;</code> / <code>§</code> 颜色码的权限，默认 <code>yuchat.chat.color</code>。</td></tr><tr><td><code>chat-format.message-color.minimessage-permission</code></td><td>允许 MiniMessage 标签的权限，默认 <code>yuchat.chat.minimessage</code>。</td></tr><tr><td><code>chat-format.message-color.hex-permission</code></td><td>允许 Hex 颜色的权限，默认 <code>yuchat.chat.hex</code>。</td></tr><tr><td><code>chat-format.message-color.placeholder-permission</code></td><td>允许聊天内容解析 PAPI 的权限，默认 <code>yuchat.chat.placeholder</code>。</td></tr></tbody></table><h2 id="component-broadcast-与悬浮" tabindex="-1">component-broadcast 与悬浮 <a class="header-anchor" href="#component-broadcast-与悬浮" aria-label="Permalink to &quot;component-broadcast 与悬浮&quot;">​</a></h2><p>默认配置优先兼容 Bukkit 原始 <code>AsyncPlayerChatEvent</code>。</p><table tabindex="0"><thead><tr><th>节点</th><th>建议</th></tr></thead><tbody><tr><td><code>chat-format.component-broadcast.enabled</code></td><td>需要聊天内 TextComponent 悬浮时再设为 <code>true</code>。</td></tr><tr><td><code>chat-format.hover.enabled</code></td><td>悬浮总开关。</td></tr><tr><td><code>chat-format.hover.message</code></td><td>聊天内容悬浮，最容易影响群组互联和聊天记录插件。</td></tr><tr><td><code>chat-format.hover.prefix</code></td><td>前缀悬浮。</td></tr><tr><td><code>chat-format.hover.suffix</code></td><td>后缀悬浮。</td></tr><tr><td><code>chat-format.hover.nickname</code></td><td>昵称悬浮。</td></tr><tr><td><code>chat-format.hover.title</code></td><td>称呼悬浮。</td></tr></tbody></table><p>只有 <code>component-broadcast.enabled</code>、<code>hover.enabled</code> 和至少一个细分悬浮开关同时开启时，YuChat 才会取消原聊天事件并自行广播 TextComponent。</p><h2 id="economy" tabindex="-1">economy <a class="header-anchor" href="#economy" aria-label="Permalink to &quot;economy&quot;">​</a></h2><p>经济节点可控制昵称、昵称颜色、昵称格式、消息颜色、个性签名、死亡消息和称呼的付费方式。</p><table tabindex="0"><thead><tr><th>支付模式</th><th>说明</th></tr></thead><tbody><tr><td><code>none</code></td><td>免费。</td></tr><tr><td><code>vault</code></td><td>使用 Vault 经济。</td></tr><tr><td><code>playerpoints</code></td><td>使用 PlayerPoints 点券。</td></tr><tr><td><code>both</code></td><td>Vault 与 PlayerPoints 都扣除。</td></tr><tr><td><code>either</code></td><td>两者二选一，优先按玩家余额可支付的一侧执行。</td></tr></tbody></table><p>常见字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>是否启用该消费项。</td></tr><tr><td><code>mode</code></td><td>支付模式。</td></tr><tr><td><code>vault-cost</code></td><td>Vault 金额。</td></tr><tr><td><code>points-cost</code></td><td>PlayerPoints 点券数量。</td></tr><tr><td><code>duration-seconds</code></td><td>使用时长，<code>0</code> 表示永久。</td></tr></tbody></table><h2 id="nickname-与-signature" tabindex="-1">nickname 与 signature <a class="header-anchor" href="#nickname-与-signature" aria-label="Permalink to &quot;nickname 与 signature&quot;">​</a></h2><table tabindex="0"><thead><tr><th>节点</th><th>说明</th></tr></thead><tbody><tr><td><code>nickname.permission</code></td><td>修改昵称所需权限，默认 <code>yuchat.nickname.use</code>。</td></tr><tr><td><code>nickname.change-permission</code></td><td>允许变更昵称的权限，默认 <code>yuchat.nickname.change</code>。</td></tr><tr><td><code>nickname.input-color-permission</code></td><td>允许普通输入中携带颜色的权限，默认 <code>yuchat.nickname.input-color</code>。</td></tr><tr><td><code>nickname.max-length</code></td><td>昵称最大长度。</td></tr><tr><td><code>nickname.cooldown-seconds</code></td><td>修改冷却。</td></tr><tr><td><code>nickname.blacklist</code></td><td>昵称黑名单。</td></tr><tr><td><code>signature.max-length</code></td><td>个性签名最大长度。</td></tr></tbody></table><h2 id="display" tabindex="-1">display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;display&quot;">​</a></h2><p><code>display</code> 控制聊天以外的展示同步。</p><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td><code>display.parse-placeholderapi</code></td><td>TAB、头顶名、Bukkit displayName 等显示格式是否解析 PAPI。</td></tr><tr><td><code>display.tab</code></td><td>同步玩家列表名。若 TAB 插件接管，推荐在 TAB 插件里使用 <code>%yuchat_tab%</code>。</td></tr><tr><td><code>display.bukkit-display-name</code></td><td>同步 Bukkit displayName，供部分插件读取。</td></tr><tr><td><code>display.nameplate</code></td><td>控制头顶名，可使用 scoreboard-team 或 hologram 模式。</td></tr><tr><td><code>display.join-message</code></td><td>加入消息格式与悬浮。</td></tr><tr><td><code>display.quit-message</code></td><td>退出消息格式与悬浮。</td></tr><tr><td><code>display.death-message</code></td><td>死亡消息、自定义死亡格式、击杀者解析和生物中文名。</td></tr></tbody></table><h2 id="titles-yml" tabindex="-1">titles.yml <a class="header-anchor" href="#titles-yml" aria-label="Permalink to &quot;titles.yml&quot;">​</a></h2><p>每个称呼包含以下常用字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>是否启用。</td></tr><tr><td><code>display-name</code></td><td>GUI 展示名。</td></tr><tr><td><code>raw-text</code></td><td>原始称呼文本。</td></tr><tr><td><code>format</code></td><td>聊天中显示的格式。</td></tr><tr><td><code>permission</code></td><td>权限拥有即视为已解锁。</td></tr><tr><td><code>temporary</code></td><td>是否默认限时。</td></tr><tr><td><code>payment</code></td><td>称呼购买费用。</td></tr><tr><td><code>effects.allowed</code></td><td>允许该称呼使用的颜色效果 ID。</td></tr><tr><td><code>effects.default</code></td><td>默认颜色效果。</td></tr><tr><td><code>icon</code></td><td>GUI 图标。</td></tr><tr><td><code>hover.lines</code></td><td>聊天中称呼悬浮文本。</td></tr></tbody></table><h2 id="effects-yml" tabindex="-1">effects.yml <a class="header-anchor" href="#effects-yml" aria-label="Permalink to &quot;effects.yml&quot;">​</a></h2><p><code>effects.yml</code> 内置多种效果：基础颜色、渐变、彩虹、闪烁、脉冲、循环等。低版本客户端会自动降级为 legacy 颜色，1.16+ 可显示 Hex 与渐变效果。</p><h2 id="reload" tabindex="-1">reload <a class="header-anchor" href="#reload" aria-label="Permalink to &quot;reload&quot;">​</a></h2><p>执行 <code>/yc reload</code> 后会重载配置、消息、GUI、称呼和效果文件。若 <code>reload.gui.reopen-main-after-reload</code> 为 <code>true</code>，正在查看 YuChat GUI 的玩家会被关闭旧界面并重开主界面，以便立即看到最新 <code>gui.yml</code>。</p>',38)])])}const p=d(r,[["render",c]]);export{b as __pageData,p as default};
